    #[test]
    fn level_two_type5_objective_advances_from_player_point_before_group8() {
        let inspection = NativeWorld::inspect_level2(level_two_fixture_path())
            .expect("qualified Level 2 package");
        let mut session = inspection
            .level2_reset_session()
            .expect("Level 2 objective point session");
        let stage = session
            .runtime()
            .stages
            .get(LEVEL2_SELECTED_OBJECTIVE_STAGE_INDEX)
            .cloned()
            .expect("selected type-5 objective stage");
        assert_eq!(stage.kind, 5);
        assert_eq!(
            session.level2_selected_objective_stage_state(),
            1,
            "frame zero starts with the source objective incomplete"
        );

        // A point just beyond the source tolerance must not advance the
        // stage, even though the same outer-turn route is otherwise live.
        session.state.position = Position {
            x: (stage.axis_x as u16).wrapping_add(LEVEL2_OBJECTIVE_POINT_RADIUS as u16 + 1),
            y: stage.axis_y as u16,
            z: 0,
        };
        session.step_outer_turn(PlayerCommand::default(), 0);
        assert_eq!(session.level2_selected_objective_stage_state(), 1);
        assert!(session.economy().spell_pickups().is_empty());

        // Entering the authored point writes state 2 after the entity pass;
        // the model-32 switch consumes it on the next source turn.
        session.state.position = Position {
            x: stage.axis_x as u16,
            y: stage.axis_y as u16,
            z: 0,
        };
        session.step_outer_turn(PlayerCommand::default(), 0);
        assert_eq!(session.level2_selected_objective_stage_state(), 2);
        assert!(session.economy().spell_pickups().is_empty());

        session.step_outer_turn(PlayerCommand::default(), 0);
        assert!(session.level2_objective_done());
        assert_eq!(session.economy().spell_pickups().len(), 2);
        assert!(session.dispatch_events().iter().any(|event| matches!(
            event,
            Level2DispatchEvent::AuthoredGroupActivated {
                group: 8,
                authored_indices,
                ..
            } if authored_indices.as_ref() == [153, 154]
        )));

        session.reset();
        assert_eq!(session.level2_selected_objective_stage_state(), 1);
        assert!(!session.level2_objective_done());
        assert!(session.economy().spell_pickups().is_empty());
    }

    #[test]
    fn level_two_model_zero_one_switches_use_strict_xy_predicates() {
        let inspection = NativeWorld::inspect_level2(level_two_fixture_path())
            .expect("qualified Level 2 switch session");
        let mut session = inspection
            .level2_reset_session()
            .expect("Level 2 switch session");
        let row_65 = session
            .mission()
            .authored_features()
            .iter()
            .find(|feature| feature.index == 65)
            .copied()
            .expect("model-zero switch row");
        let row_83 = session
            .mission()
            .authored_features()
            .iter()
            .find(|feature| feature.index == 83)
            .copied()
            .expect("model-one switch row");

        session
            .set_level2_entity_position(111, row_65.world_position(0))
            .expect("move live class-three model-zero target");
        assert!(
            session
                .level2_authored_switch_matches(65)
                .expect("model-zero overlap predicate")
        );
        assert!(
            session
                .level2_authored_switch_matches(83)
                .expect("model-one non-overlap predicate")
        );

        // Row 83 is 512 units away in Y. Moving the live model-0 target to
        // that center creates overlap and flips the model-1 predicate false.
        session
            .set_level2_entity_position(111, row_83.world_position(0))
            .expect("move live model-zero target");
        assert!(
            !session
                .level2_authored_switch_matches(83)
                .expect("model-one boundary predicate")
        );

        // Returning to the row-65 center restores strict interior overlap.
        session
            .set_level2_entity_position(111, row_65.world_position(0))
            .expect("restore live model-zero target");
        assert!(
            session
                .level2_authored_switch_matches(65)
                .expect("model-zero strict overlap predicate")
        );
        let strict_boundary = Position {
            x: row_65.world_position(0).x,
            y: row_65.world_position(0).y.wrapping_add(242),
            z: 0,
        };
        session
            .set_level2_entity_position(111, strict_boundary)
            .expect("move live model-zero target to strict boundary");
        assert!(
            !session
                .level2_authored_switch_matches(65)
                .expect("model-zero strict boundary predicate")
        );

        // A dead class-3/model-0 row is absent from remc2's linked player
        // chain, so it cannot satisfy an overlap switch even when its position
        // remains exactly at the authored center.
        session
            .set_level2_entity_position(111, row_65.world_position(0))
            .expect("restore overlap before dead-player check");
        session.entities[111].life = -1;
        assert!(
            !session
                .level2_authored_switch_matches(65)
                .expect("dead model-zero row is excluded from overlap scan")
        );
    }

    #[test]
    fn level_two_root_switch_materializes_authored_wind_on_production_turn() {
        let inspection = NativeWorld::inspect_level2(level_two_fixture_path())
            .expect("qualified Level 2 package");
        let mut session = inspection
            .level2_reset_session()
            .expect("Level 2 rooted wind-switch session");
        let root = session
            .level2_imported_switch_roots
            .iter()
            .find(|root| root.authored_index == 109 && root.target_group == 9)
            .copied()
            .expect("authored row 109 group-9 root switch");
        let wind_feature = session
            .mission()
            .authored_features()
            .iter()
            .find(|feature| feature.index == 110)
            .copied()
            .expect("authored row 110 wind feature");
        assert_eq!((wind_feature.kind, wind_feature.subtype), (10, 22));
        session.state.position = root.position;

        for _ in 0..16 {
            session.step_outer_turn(PlayerCommand::default(), 0);
            if session
                .economy()
                .authored_model22()
                .iter()
                .any(|source| source.authored_index == 110)
            {
                break;
            }
        }

        let wind = session
            .economy()
            .authored_model22()
            .iter()
            .find(|source| source.authored_index == 110)
            .copied()
            .expect("rooted group-9 switch materializes row 110 wind");
        assert_eq!(session.economy().model22_spawned_children().len(), 11);
        assert!(session.dispatch_events().iter().any(|event| matches!(
            event,
            Level2DispatchEvent::AuthoredGroupActivated {
                group: 9,
                authored_indices,
                ..
            } if authored_indices.as_ref() == [110]
        )));
        assert!(
            !session
                .level2_imported_switch_roots
                .iter()
                .find(|candidate| candidate.source_slot == root.source_slot)
                .expect("rooted row-109 switch state")
                .drawing_enabled
        );
        assert!(session.entities()[usize::from(root.source_slot)].drawing_disabled());
        assert_eq!(wind.model, 22);
        assert_eq!(wind.action, 22);

        // The source switch consumes row 110 once. Expire its temporary wind
        // parent, let the root's ten-tick cooldown clear while out of range,
        // then overlap the root again; no second authored row may appear.
        let wind_slot = wind.source_entity_index;
        session
            .economy_mut()
            .authored_model22
            .iter_mut()
            .find(|source| source.source_entity_index == wind_slot)
            .expect("live row-110 wind parent")
            .life = 0;
        session.step_outer_turn(PlayerCommand::default(), 0);
        assert!(
            session
                .economy()
                .authored_model22()
                .iter()
                .all(|source| source.authored_index != 110)
        );
        session.state.position = Position {
            x: root.position.x.wrapping_add(4_096),
            y: root.position.y,
            z: root.position.z,
        };
        for _ in 0..12 {
            session.step_outer_turn(PlayerCommand::default(), 0);
        }
        session.state.position = root.position;
        let mut second_activation = false;
        for _ in 0..16 {
            session.step_outer_turn(PlayerCommand::default(), 0);
            if session.dispatch_events().iter().any(|event| {
                matches!(
                    event,
                    Level2DispatchEvent::AuthoredGroupActivated {
                        group: 9,
                        authored_indices,
                        ..
                    } if authored_indices.as_ref() == [110]
                )
            }) {
                second_activation = true;
            }
        }
        assert!(!second_activation);
        assert!(
            session
                .economy()
                .authored_model22()
                .iter()
                .all(|source| source.authored_index != 110)
        );

        let mut boundary = inspection
            .level2_reset_session()
            .expect("Level 2 rooted wind-switch boundary session");
        boundary.state.position = Position {
            x: root.position.x,
            y: root.position.y.wrapping_add(242),
            z: root.position.z,
        };
        for _ in 0..16 {
            boundary.step_outer_turn(PlayerCommand::default(), 0);
        }
        assert!(boundary.economy().authored_model22().is_empty());
        assert!(
            boundary
                .level2_imported_switch_roots
                .iter()
                .find(|candidate| candidate.source_slot == root.source_slot)
                .expect("boundary row-109 switch state")
                .drawing_enabled
        );

        let mut dead = inspection
            .level2_reset_session()
            .expect("Level 2 rooted wind-switch dead-player session");
        dead.state.position = root.position;
        dead.entities[111].life = -1;
        for _ in 0..16 {
            dead.step_outer_turn(PlayerCommand::default(), 0);
        }
        assert!(dead.economy().authored_model22().is_empty());
        assert!(
            dead.level2_imported_switch_roots
                .iter()
                .find(|candidate| candidate.source_slot == root.source_slot)
                .expect("dead-player row-109 switch state")
                .drawing_enabled
        );
    }

    #[test]
    fn level_two_root_switches_materialize_all_authored_wind_groups() {
        let inspection = NativeWorld::inspect_level2(level_two_fixture_path())
            .expect("qualified Level 2 package");
        for (root_index, target_group, wind_index) in [
            (109, 9, 110),
            (113, 11, 114),
            (117, 13, 118),
            (121, 15, 122),
        ] {
            let mut session = inspection
                .level2_reset_session()
                .expect("Level 2 rooted wind-switch session");
            let root = session
                .level2_imported_switch_roots
                .iter()
                .find(|root| root.authored_index == root_index && root.target_group == target_group)
                .copied()
                .expect("authored rooted wind switch");
            session.state.position = root.position;
            for _ in 0..16 {
                session.step_outer_turn(PlayerCommand::default(), 0);
                if session
                    .economy()
                    .authored_model22()
                    .iter()
                    .any(|source| source.authored_index == wind_index)
                {
                    break;
                }
            }
            assert!(
                session
                    .economy()
                    .authored_model22()
                    .iter()
                    .any(|source| source.authored_index == wind_index)
            );
            assert_eq!(session.economy().model22_spawned_children().len(), 11);
            assert!(session.dispatch_events().iter().any(|event| matches!(
                event,
                Level2DispatchEvent::AuthoredGroupActivated {
                    group,
                    authored_indices,
                    ..
                } if *group == target_group && authored_indices.as_ref() == [wind_index]
            )));
            assert!(
                !session
                    .level2_imported_switch_roots
                    .iter()
                    .find(|candidate| candidate.source_slot == root.source_slot)
                    .expect("rooted wind switch state")
                    .drawing_enabled
            );
        }
    }

    #[test]
    fn level_two_wind_sub33710_writes_strict_target_mailboxes_on_cadence() {
        assert!(level2_compare_axis_with_shift(
            Position {
                x: 10_000,
                y: 10_000,
                z: 0
            },
            38,
            31,
            Position {
                x: 10_000,
                y: 10_000,
                z: 0
            },
            123,
            123,
        ));
        assert!(!level2_compare_axis_with_shift(
            Position {
                x: 10_000,
                y: 10_000,
                z: 0
            },
            38,
            31,
            Position {
                x: 10_161,
                y: 10_000,
                z: 0
            },
            123,
            123,
        ));
        let inspection = NativeWorld::inspect_level2(level_two_fixture_path())
            .expect("qualified Level 2 package");
        let mut session = inspection
            .level2_reset_session()
            .expect("Level 2 wind pulse session");
        let parent = session
            .economy_mut()
            .allocate_authored_model22(
                110,
                Position {
                    x: 20_000,
                    y: 20_000,
                    z: 0,
                },
                Position {
                    x: 20_000,
                    y: 20_000,
                    z: 0,
                },
            )
            .expect("wind parent allocation");
        let parent_slot = parent.source_entity_index;
        session
            .economy_mut()
            .authored_model22
            .iter_mut()
            .find(|source| source.source_entity_index == parent_slot)
            .expect("live wind parent")
            .phase = 8;

        // Row 1 is a qualified imported class-10/model-45 target. Rebind the
        // remote player row to model 2 so the same production scan exercises
        // the second `sub_33710` branch without adding a synthetic arena row.
        session.entities[1].set_position(parent.position);
        session.entities[112].model = 2;
        session.entities[112].record[68] = 2;
        session.entities[112].set_position(parent.position);

        session.step_outer_turn(PlayerCommand::default(), 0);
        assert_eq!(session.entities[1].source_wind_spell_payload(), 1_000);
        assert_eq!(
            session.entities[1].source_wind_spell_owner(),
            parent.entity_id
        );
        assert_eq!(session.entities[112].source_spell_word_30(), 30);
        assert_eq!(session.entities[112].activation_value, 30);
        assert_eq!(session.entities[112].word_26(), parent_slot);
        assert_eq!(session.entities[112].source_wind_spell_payload(), 1_000);
        assert_eq!(
            session.entities[112].source_wind_spell_owner(),
            parent.entity_id
        );

        // The model-45 branch is `sub_11900`: a non-zero owner replaces its
        // payload on the next firing cadence rather than accumulating it.
        session.entities[1].record[98..102].copy_from_slice(&7_i32.to_le_bytes());
        session.entities[1].record[102..104].copy_from_slice(&55_u16.to_le_bytes());
        let next_parent_position = session
            .economy()
            .authored_model22()
            .iter()
            .find(|source| source.source_entity_index == parent_slot)
            .expect("live wind parent")
            .position;
        session.entities[1].set_position(next_parent_position);
        session.entities[112].set_position(next_parent_position);
        session
            .economy_mut()
            .authored_model22
            .iter_mut()
            .find(|source| source.source_entity_index == parent_slot)
            .expect("live wind parent")
            .phase = 16;
        session.step_outer_turn(PlayerCommand::default(), 0);
        assert_eq!(session.entities[1].source_wind_spell_payload(), 1_000);
        assert_eq!(
            session.entities[1].source_wind_spell_owner(),
            parent.entity_id
        );

        // A non-firing phase leaves both target mailboxes untouched.
        let payload_before = session.entities[1].source_wind_spell_payload();
        let owner_before = session.entities[1].source_wind_spell_owner();
        session
            .economy_mut()
            .authored_model22
            .iter_mut()
            .find(|source| source.source_entity_index == parent_slot)
            .expect("live wind parent")
            .phase = 17;
        session.step_outer_turn(PlayerCommand::default(), 0);
        assert_eq!(
            session.entities[1].source_wind_spell_payload(),
            payload_before
        );
        assert_eq!(session.entities[1].source_wind_spell_owner(), owner_before);
    }

    #[test]
    fn level_two_wind_sub33340_filters_and_moves_model0_target_on_production_turn() {
        let inspection = NativeWorld::inspect_level2(level_two_fixture_path())
            .expect("qualified Level 2 package");
        let mut session = inspection
            .level2_reset_session()
            .expect("Level 2 wind movement session");
        let parent = session
            .economy_mut()
            .allocate_authored_model22(
                110,
                Position {
                    x: 20_000,
                    y: 20_000,
                    z: 0,
                },
                Position {
                    x: 20_000,
                    y: 20_000,
                    z: 0,
                },
            )
            .expect("wind parent allocation");
        let target_index = 112_u16;
        let parent_source_id = parent.entity_id;
        let spell_experience_before = *session.shared_spells().spell_experience();
        let (target_snapshot, target_speed_before) = {
            let target = session
                .entities
                .get_mut(usize::from(target_index))
                .expect("imported player target");
            assert_eq!(target.class, 3);
            target.model = 0;
            target.record[68] = 0;
            target.source_id = parent_source_id.wrapping_add(1);
            target.record[30..32].copy_from_slice(&target.source_id.to_le_bytes());
            target.set_position(parent.position);
            target.set_yaw(0);
            target.set_control_flags(0x1000_0000);
            (target.clone(), target.actual_speed)
        };
        session
            .economy_mut()
            .map_chains
            .sync_entity(RenderableMapSeed {
                entity_index: target_index,
                active: true,
                x: parent.position.x,
                y: parent.position.y,
            })
            .expect("target map chain follows its source position");

        assert!(level2_wind_sub33810_accepts(
            parent_source_id,
            &target_snapshot
        ));
        let mut rejected = target_snapshot.clone();
        rejected.model = 2;
        rejected.record[68] = 2;
        assert!(!level2_wind_sub33810_accepts(parent_source_id, &rejected));
        session.step_outer_turn(PlayerCommand::default(), 0);
        let target = &session.entities[usize::from(target_index)];
        assert_ne!(target.yaw, 0);
        assert_eq!(target.actual_speed, target_speed_before);
        assert_ne!(target.control_flags & 0x0000_0800, 0);
        assert_eq!(
            target.source_wind_spell_payload(),
            i32::from(parent.subspell_index)
        );
        assert_eq!(target.source_wind_spell_owner(), parent.entity_id);
        assert!(session.economy().map_chains().is_linked(target_index));
        // `sub_33340` terminates with `sub_6D8B0(parent_id, 0x15, count)`,
        // but AddWind's parent is class-10/model-22. The source helper only
        // awards a player entity (class 3/model 0), so this production route
        // must remain an observable no-op rather than inventing XP for the
        // wind parent.
        assert_eq!(
            *session.shared_spells().spell_experience(),
            spell_experience_before
        );

        let player_slot = match target_snapshot.special_relation {
            EntitySpecialRelation::PlayerState(slot) => slot,
            relation => panic!("model-0 target must retain player-state relation: {relation:?}"),
        };
        let roll_before = session
            .players
            .iter()
            .find(|player| player.slot == player_slot)
            .expect("target player-state row")
            .roll_0x155();
        let current_parent = session
            .economy()
            .authored_model22()
            .iter()
            .find(|source| source.source_entity_index == parent.source_entity_index)
            .copied()
            .expect("wind parent after first callback");
        let second_target_position = Position {
            x: current_parent.position.x.wrapping_add(1_024),
            y: current_parent.position.y,
            z: current_parent.position.z,
        };
        session.entities[usize::from(target_index)].set_control_flags(0);
        session.entities[usize::from(target_index)].set_position(second_target_position);
        session
            .economy_mut()
            .map_chains
            .sync_entity(RenderableMapSeed {
                entity_index: target_index,
                active: true,
                x: second_target_position.x,
                y: second_target_position.y,
            })
            .expect("second target map chain follows its source position");
        session.step_outer_turn(PlayerCommand::default(), 0);
        assert_eq!(session.entities[usize::from(target_index)].actual_speed, 80);
        let roll_after = session
            .players
            .iter()
            .find(|player| player.slot == player_slot)
            .expect("target player-state row after callback")
            .roll_0x155();
        assert_eq!(roll_after, roll_before.saturating_add(28));

        // Non-zero class-3 models use the source's wider v38/v34 bands but
        // do not receive model-0 player roll/speed feedback.
        let current_parent = session
            .economy()
            .authored_model22()
            .iter()
            .find(|source| source.source_entity_index == parent.source_entity_index)
            .copied()
            .expect("wind parent after second callback");
        let nonzero_model_position = Position {
            x: current_parent.position.x.wrapping_add(1_024),
            y: current_parent.position.y,
            z: current_parent.position.z,
        };
        {
            let target = &mut session.entities[usize::from(target_index)];
            target.model = 1;
            target.record[68] = 1;
            target.set_actual_speed(17);
            target.set_yaw(0);
            target.set_control_flags(0);
            target.set_position(nonzero_model_position);
        }
        session
            .economy_mut()
            .map_chains
            .sync_entity(RenderableMapSeed {
                entity_index: target_index,
                active: true,
                x: nonzero_model_position.x,
                y: nonzero_model_position.y,
            })
            .expect("non-zero model target map chain follows its source position");
        let nonzero_roll_before = session
            .players
            .iter()
            .find(|player| player.slot == player_slot)
            .expect("non-zero model target player-state row")
            .roll_0x155();
        session.step_outer_turn(PlayerCommand::default(), 0);
        let nonzero_model_target = &session.entities[usize::from(target_index)];
        assert_eq!(nonzero_model_target.actual_speed, 17);
        assert_eq!(nonzero_model_target.yaw, 204);
        assert_ne!(nonzero_model_target.control_flags & 0x0000_0800, 0);
        assert_eq!(
            session
                .players
                .iter()
                .find(|player| player.slot == player_slot)
                .expect("non-zero model target player-state row after callback")
                .roll_0x155(),
            nonzero_roll_before
        );

        // The class-10 allowlist in sub_33810 is independent of the
        // class-3 model check. Model 39 takes the same non-player movement
        // branch and still receives the source hit mailbox when airborne.
        let class10_parent = session
            .economy()
            .authored_model22()
            .iter()
            .find(|source| source.source_entity_index == parent.source_entity_index)
            .copied()
            .expect("wind parent after non-zero model callback");
        let class10_position = Position {
            x: class10_parent.position.x.wrapping_add(1_024),
            y: class10_parent.position.y,
            z: class10_parent.position.z,
        };
        {
            let target = &mut session.entities[usize::from(target_index)];
            target.class = 10;
            target.record[67] = 10;
            target.model = 39;
            target.record[68] = 39;
            target.set_actual_speed(23);
            target.set_yaw(0);
            target.set_control_flags(0x1000_0000);
            target.set_position(class10_position);
        }
        session
            .economy_mut()
            .map_chains
            .sync_entity(RenderableMapSeed {
                entity_index: target_index,
                active: true,
                x: class10_position.x,
                y: class10_position.y,
            })
            .expect("class-10 target map chain follows its source position");
        let class10_snapshot = session.entities[usize::from(target_index)].clone();
        assert!(level2_wind_sub33810_accepts(
            parent_source_id,
            &class10_snapshot
        ));
        let mut rejected_class10 = class10_snapshot.clone();
        rejected_class10.model = 45;
        rejected_class10.record[68] = 45;
        assert!(!level2_wind_sub33810_accepts(
            parent_source_id,
            &rejected_class10
        ));
        session.step_outer_turn(PlayerCommand::default(), 0);
        let class10_target = &session.entities[usize::from(target_index)];
        assert_eq!(class10_target.actual_speed, 23);
        assert_eq!(class10_target.yaw, 204);
        assert_ne!(class10_target.control_flags & 0x0000_0800, 0);
        assert_eq!(
            class10_target.source_wind_spell_payload(),
            i32::from(parent.subspell_index)
        );
        assert_eq!(class10_target.source_wind_spell_owner(), parent.entity_id);

        // The remaining class-2 allowlist is just models 7/8 and shares the
        // same non-v40 movement branch.
        let class2_parent = session
            .economy()
            .authored_model22()
            .iter()
            .find(|source| source.source_entity_index == parent.source_entity_index)
            .copied()
            .expect("wind parent after class-10 callback");
        let class2_position = Position {
            x: class2_parent.position.x.wrapping_add(1_024),
            y: class2_parent.position.y,
            z: class2_parent.position.z,
        };
        {
            let target = &mut session.entities[usize::from(target_index)];
            target.class = 2;
            target.record[67] = 2;
            target.model = 7;
            target.record[68] = 7;
            target.action = 0;
            target.record[73] = 0;
            target.set_actual_speed(31);
            target.set_yaw(0);
            target.set_control_flags(0);
            target.set_position(class2_position);
        }
        session
            .economy_mut()
            .map_chains
            .sync_entity(RenderableMapSeed {
                entity_index: target_index,
                active: true,
                x: class2_position.x,
                y: class2_position.y,
            })
            .expect("class-2 target map chain follows its source position");
        let class2_snapshot = session.entities[usize::from(target_index)].clone();
        assert!(level2_wind_sub33810_accepts(
            parent_source_id,
            &class2_snapshot
        ));
        let mut rejected_class2 = class2_snapshot.clone();
        rejected_class2.model = 6;
        rejected_class2.record[68] = 6;
        assert!(!level2_wind_sub33810_accepts(
            parent_source_id,
            &rejected_class2
        ));
        session.step_outer_turn(PlayerCommand::default(), 0);
        let class2_target = &session.entities[usize::from(target_index)];
        assert_eq!(class2_target.actual_speed, 31);
        assert_eq!(class2_target.yaw, 204);
        assert_ne!(class2_target.control_flags & 0x0000_0800, 0);
        assert_eq!(class2_target.source_wind_spell_owner(), parent.entity_id);

        // Class 5 admits model 13 when its action is not one of the two
        // source-excluded action values; action 180 must remain untouched.
        let class5_parent = session
            .economy()
            .authored_model22()
            .iter()
            .find(|source| source.source_entity_index == parent.source_entity_index)
            .copied()
            .expect("wind parent after class-2 callback");
        let class5_position = Position {
            x: class5_parent.position.x.wrapping_add(1_024),
            y: class5_parent.position.y,
            z: class5_parent.position.z,
        };
        {
            let target = &mut session.entities[usize::from(target_index)];
            target.class = 5;
            target.record[67] = 5;
            target.model = 13;
            target.record[68] = 13;
            target.action = 0;
            target.record[73] = 0;
            target.set_actual_speed(37);
            target.set_yaw(0);
            target.set_control_flags(0);
            target.set_position(class5_position);
        }
        session
            .economy_mut()
            .map_chains
            .sync_entity(RenderableMapSeed {
                entity_index: target_index,
                active: true,
                x: class5_position.x,
                y: class5_position.y,
            })
            .expect("class-5 target map chain follows its source position");
        let class5_snapshot = session.entities[usize::from(target_index)].clone();
        assert!(level2_wind_sub33810_accepts(
            parent_source_id,
            &class5_snapshot
        ));
        let mut rejected_class5 = class5_snapshot.clone();
        rejected_class5.action = 180;
        rejected_class5.record[73] = 180;
        assert!(!level2_wind_sub33810_accepts(
            parent_source_id,
            &rejected_class5
        ));
        session.step_outer_turn(PlayerCommand::default(), 0);
        let class5_target = &session.entities[usize::from(target_index)];
        assert_eq!(class5_target.actual_speed, 37);
        assert_eq!(class5_target.yaw, 204);
        assert_ne!(class5_target.control_flags & 0x0000_0800, 0);
        assert_eq!(class5_target.source_wind_spell_owner(), parent.entity_id);

        // Exercise the negative through the real production turn as well:
        // action 180 is rejected before any movement/mailbox mutation.
        let rejected_parent = session
            .economy()
            .authored_model22()
            .iter()
            .find(|source| source.source_entity_index == parent.source_entity_index)
            .copied()
            .expect("wind parent after class-5 callback");
        let rejected_position = Position {
            x: rejected_parent.position.x.wrapping_add(1_024),
            y: rejected_parent.position.y,
            z: rejected_parent.position.z,
        };
        {
            let target = &mut session.entities[usize::from(target_index)];
            target.action = 180;
            target.record[73] = 180;
            target.set_actual_speed(41);
            target.set_yaw(0);
            target.set_control_flags(0);
            target.set_position(rejected_position);
        }
        session
            .economy_mut()
            .map_chains
            .sync_entity(RenderableMapSeed {
                entity_index: target_index,
                active: true,
                x: rejected_position.x,
                y: rejected_position.y,
            })
            .expect("rejected class-5 target map chain follows its source position");
        session.step_outer_turn(PlayerCommand::default(), 0);
        let rejected_target = &session.entities[usize::from(target_index)];
        assert_eq!(rejected_target.actual_speed, 41);
        assert_eq!(rejected_target.yaw, 0);
        assert_eq!(rejected_target.control_flags & 0x0000_0800, 0);
    }

    #[test]
    fn level_two_imported_model1_root_hides_after_inverse_overlap_success() {
        let inspection = NativeWorld::inspect_level2(level_two_fixture_path())
            .expect("qualified Level 2 package");
        let mut session = inspection
            .level2_reset_session()
            .expect("Level 2 imported model-1 switch session");
        // The qualified Level 2 owner fixture currently imports only the
        // model-0 members of this source family. Rebind one imported root to
        // the pinned `CheckpointArrived_6F070` model-1 callback so this
        // production-turn test exercises the inverse-overlap branch without
        // fabricating a second owner package or weakening its manifest.
        let root = session
            .level2_imported_switch_roots
            .iter()
            .find(|root| root.model == 0)
            .copied()
            .expect("fixture has an imported model-0 root switch");
        session
            .level2_imported_switch_roots
            .iter_mut()
            .find(|candidate| candidate.source_slot == root.source_slot)
            .expect("imported root state")
            .model = 1;
        session.entities[usize::from(root.source_slot)].model = 1;
        session.state.position = Position {
            x: root.position.x.wrapping_add(4_096),
            y: root.position.y,
            z: root.position.z,
        };

        for _ in 0..16 {
            session.step_outer_turn(PlayerCommand::default(), 0);
            if !session
                .level2_imported_switch_roots
                .iter()
                .find(|candidate| candidate.source_slot == root.source_slot)
                .expect("imported model-1 root state")
                .drawing_enabled
            {
                break;
            }
        }

        assert!(
            !session
                .level2_imported_switch_roots
                .iter()
                .find(|candidate| candidate.source_slot == root.source_slot)
                .expect("imported model-1 root state")
                .drawing_enabled
        );
        assert!(session.entities()[usize::from(root.source_slot)].drawing_disabled());
    }

