    #[test]
    fn level_two_spell_replacement_uses_shared_arena_and_outer_cursor() {
        let inspection = NativeWorld::inspect_level2(level_two_fixture_path())
            .expect("qualified Level 2 package");
        let mut session = inspection
            .level2_reset_session()
            .expect("Level 2 spell-replacement session");
        let baseline_hash = session.economy().reset_hash();
        let first_free = *session
            .economy()
            .free_slots
            .last()
            .expect("source free slot");
        let consumed_slot = session
            .economy_mut()
            .spawn_mana_carrier(Position::default(), 111, 0)
            .expect("shared arena carrier allocation");
        assert_eq!(consumed_slot, first_free);
        let expected_slot = *session
            .economy()
            .free_slots
            .last()
            .expect("next source free slot");
        let global_rng = session.economy().global_rng;
        let position = Position {
            x: 2_048,
            y: 4_096,
            z: 128,
        };
        let replacement = session
            .allocate_level2_spell_replacement(11, 38, position)
            .expect("family-11 replacement allocation");
        assert_eq!(replacement.source_entity_index, expected_slot);
        assert_eq!(
            replacement.entity_rng,
            expected_slot.wrapping_add(global_rng as u16)
        );
        assert_eq!(replacement.parent_entity_index, 38);
        assert_eq!(replacement.position, position);
        assert_eq!(replacement.family, 11);
        assert_eq!(replacement.action, 35);
        assert_eq!(replacement.phase, expected_slot as u8);
        assert_eq!(replacement.control_flags, 0);
        assert!(replacement.active);
        assert!(
            session
                .economy()
                .map_chains()
                .linked_entity_indices()
                .contains(&expected_slot)
        );
        assert!(
            session
                .economy()
                .live_arena_slots()
                .contains(&(expected_slot, Level2DynamicArenaKind::SpellReplacement))
        );

        session.step_outer_turn(PlayerCommand::default(), 0);
        assert!(session.dispatch_events().iter().any(|event| matches!(
            event,
            Level2DispatchEvent::DynamicArena {
                source_slot,
                kind: Level2DynamicArenaKind::SpellReplacement,
                ..
            } if *source_slot == expected_slot
        )));
        assert_eq!(
            session
                .economy()
                .spell_replacements()
                .iter()
                .find(|row| row.source_entity_index == expected_slot)
                .expect("live replacement")
                .phase,
            replacement.phase.wrapping_add(1)
        );

        session
            .economy_mut()
            .spell_replacements
            .iter_mut()
            .find(|row| row.source_entity_index == expected_slot)
            .expect("replacement to reclaim")
            .active = false;
        session.economy_mut().reclaim_inactive_slots();
        assert!(session.economy().spell_replacements().is_empty());
        assert!(session.economy().free_slots.contains(&expected_slot));
        assert!(
            !session
                .economy()
                .map_chains()
                .linked_entity_indices()
                .contains(&expected_slot)
        );

        session.economy_mut().free_slots.clear();
        let rows_before_failure = session.economy().spell_replacements().len();
        assert!(
            session
                .allocate_level2_spell_replacement(6, 155, position)
                .is_none()
        );
        assert_eq!(
            session.economy().spell_replacements().len(),
            rows_before_failure
        );
        session.reset();
        assert_eq!(session.economy().reset_hash(), baseline_hash);
        assert!(session.economy().spell_replacements().is_empty());
        assert!(session.economy().carriers().is_empty());
    }

    #[test]
    fn level_two_persistent_replacement_reaches_production_acquisition_and_reallocates() {
        let inspection = NativeWorld::inspect_level2(level_two_fixture_path())
            .expect("qualified Level 2 package");
        let mut session = inspection
            .level2_reset_session()
            .expect("Level 2 persistent replacement session");
        let position = Position {
            x: 3_072,
            y: 5_120,
            z: 128,
        };
        let first = session
            .allocate_level2_spell_replacement(11, 38, position)
            .expect("persistent family-11 source allocation");
        session.state.position = position;
        let mut acquired = None;
        for _ in 0..4 {
            session.step_outer_turn(PlayerCommand::default(), 0);
            acquired = session
                .dispatch_events()
                .iter()
                .find_map(|event| match event {
                    Level2DispatchEvent::SpellAcquisition {
                        family: 11,
                        source_slot,
                        result: Some(outcome),
                        ..
                    } => Some((*source_slot, *outcome)),
                    _ => None,
                });
            if acquired.is_some() {
                break;
            }
        }
        let (source_slot, outcome) = acquired.expect("persistent family-11 source acquisition");
        assert_eq!(source_slot, first.source_entity_index);
        assert_eq!(outcome.holder_action, 33);
        assert_eq!(outcome.replacement_action, Some(35));
        let rows = session.economy().spell_replacements();
        let holder = rows
            .iter()
            .find(|row| row.source_entity_index == first.source_entity_index)
            .expect("acquired persistent source remains in arena");
        assert_eq!(holder.action, 33);
        let replacement = rows
            .iter()
            .find(|row| row.source_entity_index != first.source_entity_index && row.action == 35)
            .expect("sub_69250 replacement source");
        assert_eq!(replacement.family, 11);
        assert_eq!(replacement.parent_entity_index, outcome.parent_entity_index);
        assert_eq!(replacement.position, position);
        assert!(
            session
                .shared_spells()
                .dynamic_pickups()
                .iter()
                .any(|entity| {
                    entity.index == replacement.source_entity_index && entity.action == 35
                })
        );
        assert_eq!(
            session
                .shared_spells()
                .persistent_acquisition_states()
                .get(&replacement.source_entity_index)
                .expect("persistent family-11 acquisition state")
                .source_slot,
            replacement.source_entity_index
        );
    }

    #[test]
    fn level_two_runagain_dispatches_reclaimed_slot_reuse_with_new_generation() {
        // Two overlapping live spheres make the first source handler retire
        // one arena occupant; the later persistent pickup then reuses that
        // numeric slot in the same outer turn. This is the source-order case
        // that a slot-only dispatched set silently drops.
        let inspection = NativeWorld::inspect_level2(level_two_fixture_path())
            .expect("qualified Level 2 package");
        let mut session = inspection
            .level2_reset_session()
            .expect("Level 2 runagain slot-reuse session");
        let baseline_campaign_hash = session.campaign_state_hash();
        let free_slots = session
            .economy()
            .free_slots
            .iter()
            .rev()
            .copied()
            .collect::<Vec<_>>();
        let prefix_allocations = free_slots
            .iter()
            .enumerate()
            .find_map(|(index, _)| {
                (index + 2 < free_slots.len() && free_slots[index + 2] % 4 == 0).then_some(index)
            })
            .expect(
                "free slot whose later persistent replacement cadence is immediately collectable",
            );
        for _ in 0..prefix_allocations {
            let _ = session
                .economy_mut()
                .spawn_mana_carrier(Position::default(), 111, 0)
                .expect("prefix carrier allocation");
        }
        let target_slot = u16::try_from(
            session
                .economy_mut()
                .spawn_mana_sphere_from_death(901, Position::default(), 0, 0x1111, 100, 111)
                .expect("target sphere allocation"),
        )
        .expect("target sphere slot fits");
        let second_sphere_slot = u16::try_from(
            session
                .economy_mut()
                .spawn_mana_sphere_from_death(902, Position::default(), 0, 0x2222, 50, 111)
                .expect("source sphere allocation"),
        )
        .expect("source sphere slot fits");
        let persistent = session
            .allocate_level2_spell_replacement(11, 38, Position::default())
            .expect("persistent replacement allocation");
        session.state.position = persistent.position;
        assert_eq!(target_slot, free_slots[prefix_allocations]);
        assert_eq!(second_sphere_slot, free_slots[prefix_allocations + 1]);
        assert_eq!(
            persistent.source_entity_index,
            free_slots[prefix_allocations + 2]
        );
        let reused_slot = target_slot;
        assert_eq!(
            session.economy().free_slot_count(),
            free_slots.len() - prefix_allocations - 3
        );
        for slot in [target_slot, second_sphere_slot] {
            let sphere = session
                .economy_mut()
                .spheres
                .iter_mut()
                .find(|sphere| sphere.source_entity_index == slot)
                .expect("test sphere remains live before source dispatch");
            sphere.position = Position::default();
            sphere.velocity_x = 0;
            sphere.velocity_y = 0;
            sphere.vertical_velocity = 0;
        }
        assert_eq!(
            session
                .economy()
                .spell_replacements()
                .iter()
                .find(
                    |replacement| replacement.source_entity_index == persistent.source_entity_index
                )
                .expect("initial persistent source")
                .action,
            35
        );
        assert_eq!(
            session
                .economy()
                .live_arena_cursor_rows()
                .into_iter()
                .find(|row| row.source_slot == reused_slot)
                .expect("initial cursor row")
                .generation,
            1
        );

        session.step_outer_turn(PlayerCommand::default(), 0);

        assert!(session.dispatch_events().iter().any(|event| matches!(
            event,
            Level2DispatchEvent::DynamicArena {
                source_slot,
                kind: Level2DynamicArenaKind::ManaSphere,
                ..
            } if *source_slot == target_slot
        )));
        assert!(session.dispatch_events().iter().any(|event| matches!(
            event,
            Level2DispatchEvent::SpellAcquisition {
                family: 11,
                source_slot,
                result: Some(_),
                ..
            } if *source_slot == persistent.source_entity_index
        )));
        let first_target_visit = session
            .dispatch_events()
            .iter()
            .position(|event| {
                matches!(
                    event,
                    Level2DispatchEvent::DynamicArena {
                        source_slot,
                        kind: Level2DynamicArenaKind::ManaSphere,
                        ..
                    } if *source_slot == target_slot
                )
            })
            .expect("target sphere is visited before its slot is reused");
        let reused_slot_visit = session
            .dispatch_events()
            .iter()
            .position(|event| {
                matches!(
                    event,
                    Level2DispatchEvent::DynamicArena {
                        source_slot,
                        kind: Level2DynamicArenaKind::SpellReplacement,
                        ..
                    } if *source_slot == reused_slot
                )
            })
            .expect("reused slot is revisited as a replacement");
        assert!(
            first_target_visit < reused_slot_visit,
            "reused slot must be revisited after its original source visit"
        );
        assert_eq!(
            session
                .dispatch_events()
                .iter()
                .filter(|event| matches!(
                    event,
                    Level2DispatchEvent::DynamicArena {
                        source_slot,
                        kind: Level2DynamicArenaKind::SpellReplacement,
                        ..
                    } if *source_slot == reused_slot
                ))
                .count(),
            1,
            "runagain must revisit a reclaimed slot after a new allocation reuses it"
        );
        let replacement = session
            .economy()
            .spell_replacements()
            .iter()
            .find(|replacement| replacement.source_entity_index == reused_slot)
            .expect("replacement reused reclaimed slot");
        assert_eq!(replacement.family, 11);
        assert_eq!(replacement.action, 35);
        assert_eq!(
            session
                .economy()
                .live_arena_cursor_rows()
                .into_iter()
                .find(|row| row.source_slot == reused_slot)
                .expect("replacement cursor row")
                .generation,
            2
        );
        session.reset();
        assert_eq!(session.campaign_state_hash(), baseline_campaign_hash);
    }

